SELECT session_id, DATE_TRUNC('YEAR', event_time) AS year_start, PERCENTILE_APPROX(duration_sec, 0.5) AS duration_sec_p50, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT_IF(event_type = 'search') AS search_events, MIN(event_time) AS first_event_time, COUNT_IF(page = '/cart') AS cart_events, MIN(event_time) AS first_seen FROM web_events GROUP BY 1, 2 HAVING COUNT_IF(event_type = 'search') > 1;
